<script setup lang="ts">
import { onMounted, ref } from 'vue'
type Medication={id:number;name:string;generic_name?:string;strength?:string;unit:string}
const items=ref<Medication[]>([]),form=ref({name:'',generic_name:'',strength:'',unit:'tablet',description:''}),error=ref(''),saved=ref('');const base=import.meta.env.VITE_API_BASE_URL??'http://127.0.0.1:8010/api/v1';const headers={Authorization:`Bearer ${sessionStorage.getItem('tb_token')}`,Accept:'application/json'}
async function load(){try{const r=await fetch(`${base}/medications`,{headers});items.value=(await r.json()).data}catch{error.value='Gagal memuat obat.'}}onMounted(load)
async function submit(){error.value='';try{const r=await fetch(`${base}/medications`,{method:'POST',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify(form.value)});const p=await r.json();if(!r.ok)throw new Error(p.message??'Gagal menyimpan obat.');saved.value='Obat berhasil disimpan.';form.value={name:'',generic_name:'',strength:'',unit:'tablet',description:''};await load()}catch(e){error.value=e instanceof Error?e.message:'Gagal menyimpan obat.'}}
</script>
<template><main class="admin-page"><section class="admin-content"><header><div><p>Master data</p><h1>Data Obat</h1></div></header><form class="panel form-grid" @submit.prevent="submit"><label>Nama Obat<input v-model="form.name" required></label><label>Nama Generik<input v-model="form.generic_name"></label><label>Kekuatan / Dosis<input v-model="form.strength"></label><label>Satuan<input v-model="form.unit" required></label><label class="wide">Keterangan<textarea v-model="form.description" /></label><p v-if="error" class="login-error wide">{{error}}</p><p v-if="saved" class="success wide">{{saved}}</p><button class="save-button wide">Simpan Obat</button></form><section class="panel"><table><thead><tr><th>Nama</th><th>Generik</th><th>Kekuatan</th><th>Satuan</th></tr></thead><tbody><tr v-if="!items.length"><td colspan="4">Belum ada obat.</td></tr><tr v-for="item in items" :key="item.id"><td>{{item.name}}</td><td>{{item.generic_name??'-'}}</td><td>{{item.strength??'-'}}</td><td>{{item.unit}}</td></tr></tbody></table></section></section></main></template>
